<?php
require __DIR__.'/security.php';security_establish_session($ou);
$cash=funds_create('FX AFN cash','cash','AFN',1000);$usd=funds_create('FX USD cash','cash','USD',100);
$p=['kind'=>'exchange','request_key'=>bin2hex(random_bytes(16)),'source_account'=>$usd,'destination_account'=>$cash,'source_amount'=>10,'target_amount'=>700,'document_date'=>date('Y-m-d'),'reason'=>'Signed exchange receipt'];$id=fx_post($p);check(funds_balance($usd)==='90.00'&&funds_balance($cash)==='1700.00','documented exchange moves only the agreed amounts in each currency');check(fx_post($p)===$id&&funds_balance($usd)==='90.00','currency exchange retry cannot move funds twice');$bad=$p;$bad['target_amount']=701;$caught=false;try{fx_post($bad);}catch(InvalidArgumentException $e){$caught=true;}check($caught,'exchange request cannot change the agreed amount');
$pdo->prepare("INSERT INTO debts (customer_name,total_amount,paid_amount,remaining_amount,debt_type,currency_code,shop_id) VALUES ('FX receivable',140,0,140,'receivable','AFN',?)")->execute([shop_id()]);$debt=(int)$pdo->lastInsertId();$p=['kind'=>'debt','request_key'=>bin2hex(random_bytes(16)),'source_account'=>$usd,'debt_id'=>$debt,'source_amount'=>2,'target_amount'=>140,'document_date'=>date('Y-m-d'),'reason'=>'Customer agreed USD settlement'];fx_post($p);check(funds_balance($usd)==='92.00','foreign receivable settlement receives actual USD');$q=$pdo->prepare('SELECT remaining_amount FROM debts WHERE id=?');$q->execute([$debt]);check(dec_units($q->fetchColumn())===0,'foreign settlement clears the exact invoice-currency debt');
$pdo->prepare("INSERT INTO debts (customer_name,total_amount,paid_amount,remaining_amount,debt_type,currency_code,shop_id) VALUES ('FX payable',70,0,70,'payable','AFN',?)")->execute([shop_id()]);$payable=(int)$pdo->lastInsertId();$p['debt_id']=$payable;$p['request_key']=bin2hex(random_bytes(16));$p['source_amount']=1;$p['target_amount']=70;fx_post($p);check(funds_balance($usd)==='91.00','foreign payable settlement pays actual USD without mixing currencies');
$pdo->prepare('INSERT INTO sales (invoice_no,customer_name,total_amount,paid_amount,remaining_amount,profit,currency_code,shop_id,created_at) VALUES (?,?,140,0,140,0,?,?,?)')->execute(['FX-'.bin2hex(random_bytes(6)),'Foreign buyer','AFN',shop_id(),date('Y-m-d H:i:s')]);$sale=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO debts (sale_id,customer_name,total_amount,paid_amount,remaining_amount,debt_type,currency_code,shop_id) VALUES (?,'Foreign buyer',140,0,140,'receivable','AFN',?)")->execute([$sale,shop_id()]);$debt=(int)$pdo->lastInsertId();$_POST=['cash_account_id'=>$usd,'payment_currency_code'=>'USD','received_amount'=>2];finance_post('sale',$sale,'AFN',date('Y-m-d'),'Foreign invoice',[['1100',140,0],['4000',0,140]]);$receipt=funds_record($usd,'in',2,'2900','sale',$sale,bin2hex(random_bytes(16)),date('Y-m-d'),'Original foreign receipt');$_POST=[];$before=funds_balance($usd);
$p=['kind'=>'receipt','request_key'=>bin2hex(random_bytes(16)),'debt_id'=>$debt,'receipt_id'=>$receipt,'source_amount'=>1,'target_amount'=>70,'document_date'=>date('Y-m-d'),'reason'=>'Allocate original receipt'];fx_post($p);check(funds_balance($usd)===$before,'allocation of existing foreign receipt never collects cash twice');

$bad=$p;$bad['request_key']=bin2hex(random_bytes(16));$bad['source_amount']='1.01';$caught=false;try{fx_post($bad);}catch(InvalidArgumentException $e){$caught=true;}check($caught,'foreign receipt cannot be allocated beyond its unused amount');
$p['request_key']=bin2hex(random_bytes(16));$last=fx_post($p);check(fx_post($p)===$last,'foreign receipt allocation retry is idempotent');$q=$pdo->prepare('SELECT remaining_amount,paid_amount FROM sales WHERE id=?');$q->execute([$sale]);$row=$q->fetch();check(dec_units($row['remaining_amount'])===0&&dec_round($row['paid_amount'])==='140.00','foreign receipt allocations update invoice balances in invoice currency');
$p=['kind'=>'exchange','request_key'=>bin2hex(random_bytes(16)),'source_account'=>$cash,'destination_account'=>$cash,'source_amount'=>1,'target_amount'=>1,'document_date'=>date('Y-m-d'),'reason'=>'Invalid same currency'];$caught=false;try{fx_post($p);}catch(InvalidArgumentException $e){$caught=true;}check($caught,'same-currency document cannot masquerade as an FX exchange');
finance_close_period(date('Y-m-d'));$p['request_key']=bin2hex(random_bytes(16));$p['destination_account']=$usd;$p['target_amount']='0.01';$before=funds_balance($cash);$caught=false;try{fx_post($p);}catch(InvalidArgumentException $e){$caught=true;}check($caught&&funds_balance($cash)===$before,'closed period rolls back both sides of an exchange');
$q=$pdo->prepare('SELECT h.currency_code,SUM(d.debit-d.credit) AS difference FROM journal_headers h JOIN journal_details d ON d.journal_id=h.id AND d.shop_id=h.shop_id WHERE h.shop_id=? GROUP BY h.currency_code');$q->execute([shop_id()]);foreach($q->fetchAll() as $row)check(dec_units($row['difference'])===0,'exchange journals balance independently for '.$row['currency_code']);
echo "Foreign currency settlement scenarios completed.\n";
